package dev.nikarh.bandcontrol.core.protocol

import dev.nikarh.bandcontrol.proto.ClientMessage
import dev.nikarh.bandcontrol.proto.ServerMessage
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** Checks the Kotlin implementation against `proto/test-vectors.json`, generated by the Rust implementation. */
class VectorsTest {
    private val vectors = JSONObject(File(System.getProperty("bandcontrol.vectors")).readText())

    private fun String.hex(): ByteArray = chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    private fun ByteArray.hex(): String = joinToString("") { "%02x".format(it) }

    private fun JSONArray.objects() = (0 until length()).map { getJSONObject(it) }

    private fun JSONArray.strings() = (0 until length()).map { getString(it) }

    @Test
    fun pairing() {
        for (case in vectors.getJSONArray("pairing").objects()) {
            val secret = PairingSecret(case.getString("secret").hex())
            assertEquals(case.getString("code"), secret.toCode())
            assertEquals(case.getString("display_code"), secret.toDisplayCode())
            assertEquals(secret, PairingSecret.fromCode(case.getString("display_code").lowercase()))
            assertEquals(case.getString("service_uuid"), Crypto.serviceUuid(secret).toString())
            val info = PairingInfo(secret, case.getString("name"))
            assertEquals(case.getString("url"), info.toUrl())
            assertEquals(info, PairingInfo.fromUrl(case.getString("url")))
        }
    }

    @Test
    fun invalidCodesAreRejected() {
        assertNull(PairingSecret.fromCode("AAAA"))
        assertNull(PairingSecret.fromCode("AAAAAAAAAAAAAAAAAAAAAAAAA1"))
        // Non-zero trailing bits.
        assertNull(PairingSecret.fromCode("AAAAAAAAAAAAAAAAAAAAAAAAAB"))
        assertNull(PairingInfo.fromUrl("https://example.com/?s=AAAAAAAAAAAAAAAAAAAAAAAAAA"))
    }

    @Test
    fun proofsAndKeys() {
        val v = vectors.getJSONObject("proofs")
        val key = AuthKey(PairingSecret(v.getString("secret").hex()))
        val cn = v.getString("client_nonce").hex()
        val sn = v.getString("server_nonce").hex()
        val session = v.getInt("session_id")
        assertEquals(v.getString("server_proof"), key.serverProof(cn, sn, session).hex())
        assertEquals(v.getString("client_proof"), key.clientProof(cn, sn, session).hex())
        assertTrue(key.verifyServerProof(cn, sn, session, v.getString("server_proof").hex()))
        val (s2c, c2s) = key.sessionKeys(cn, sn)
        assertEquals(v.getString("s2c"), s2c.hex())
        assertEquals(v.getString("c2s"), c2s.hex())
    }

    @Test
    fun aead() {
        val v = vectors.getJSONObject("aead")
        val key = v.getString("key").hex()
        val sealer = Sealer(key)
        val opener = Opener(key)
        for (m in v.getJSONArray("unicast").objects()) {
            val ciphertext = sealer.seal(m.getString("plaintext").hex())
            assertEquals(m.getString("ciphertext"), ciphertext.hex())
            assertArrayEquals(m.getString("plaintext").hex(), opener.open(ciphertext))
        }
        val broadcast = BroadcastOpener(key)
        val frames = v.getJSONArray("broadcast").objects()
        for (f in frames) {
            assertEquals(f.getString("plaintext"), broadcast.open(f.getString("frame").hex()).hex())
        }
        // Replays are rejected.
        val replay = runCatching { broadcast.open(frames.first().getString("frame").hex()) }
        assertTrue(replay.exceptionOrNull() is DecryptException)
    }

    @Test
    fun framing() {
        for (case in vectors.getJSONArray("framing").objects()) {
            val message = case.getString("message").hex()
            val packets = Framing.fragment(case.getInt("channel"), message, case.getInt("max_packet"))
            assertEquals(case.getJSONArray("packets").strings(), packets.map { it.hex() })
            val reassembler = Reassembler()
            val results = packets.mapNotNull(reassembler::push)
            assertEquals(1, results.size)
            assertEquals(case.getInt("channel"), results[0].first)
            assertArrayEquals(message, results[0].second)
        }
    }

    @Test
    fun recordedSession() {
        val v = vectors.getJSONObject("session")
        val client =
            ClientSession(
                PairingSecret(v.getString("secret").hex()),
                v.getString("client_name"),
                v.getInt("max_packet"),
                v.getString("client_nonce").hex(),
            )

        var clientPackets = client.hello()
        for (step in v.getJSONArray("handshake").objects()) {
            assertEquals(step.getJSONArray("client").strings(), clientPackets.map { it.hex() })
            val events = step.getJSONArray("server").strings().flatMap { client.receive(it.hex()) }
            clientPackets = events.filterIsInstance<ClientEvent.Send>().flatMap { it.packets }
            val expected =
                step.getJSONArray("events").objects().map {
                    val a = it.getJSONObject("authenticated")
                    ClientEvent.Authenticated(a.getInt("session"), a.getString("server_name"))
                }
            assertEquals(expected, events.filterIsInstance<ClientEvent.Authenticated>())
        }
        assertTrue(clientPackets.isEmpty())
        assertTrue(client.isReady)

        val messages = v.getJSONArray("server_packets").strings().flatMap { client.receive(it.hex()) }
        assertEquals(
            v.getJSONArray("messages").strings().map { ServerMessage.ADAPTER.decode(it.hex()) },
            messages.map { (it as ClientEvent.Message).message },
        )
        assertEquals(
            v.getJSONArray("messages").strings(),
            messages.map { (it as ClientEvent.Message).message.encode().hex() },
        )

        for (command in v.getJSONArray("commands").objects()) {
            val message = ClientMessage.ADAPTER.decode(command.getString("message").hex())
            assertEquals(command.getString("message"), message.encode().hex())
            assertEquals(command.getJSONArray("packets").strings(), client.send(message).map { it.hex() })
        }
    }
}
